package config

// SampleConfigTemplate is a documented starter configuration generated by `tcbroker init`.
const SampleConfigTemplate = `# tcbroker mini-NPB configuration
# Apply with:   sudo tcbroker apply tcbroker.yaml
# Check status: tcbroker status
# Launch WebUI: sudo tcbroker serve
# Stop all:     sudo tcbroker stop

# Optional human-readable labels for interfaces (shown in CLI status & WebUI)
ports:
  eth0:
    label: wan-uplink
    role: tap
  eth1:
    label: suricata-ids
    role: tool
  eth2:
    label: zeek-ndr
    role: tool

rules:
  # Example 1: Mirror all IPv4 ingress traffic from eth0 to eth1
  # (omitting 'filters' matches all IPv4 traffic; 'direction' defaults to 'ingress')
  - name: mirror-all
    src: eth0
    dst: eth1

  # Example 2: Filter HTTP/HTTPS, tag with VLAN 100, and cap mirror rate at 500mbit
  - name: web-traffic
    src: eth0
    direction: ingress # ingress | egress | both
    rate_limit:
      rate: 500mbit
    dst:
      - intf: eth1
        vlan:
          push: 100
      - eth2
    filters:
      - proto: tcp
        dst_port: 80
      - proto: tcp
        dst_port: 443

  # Example 3: Mirror with MAC/IP header rewrite for shadow replay
  # - name: dns-shadow
  #   src: eth0
  #   dst:
  #     - intf: eth1
  #       rewrite:
  #         dst_mac: "52:54:00:12:34:56"
  #         dst_ip: "10.0.0.100"
  #   filters:
  #     - proto: udp
  #       src_ip: 192.168.10.0/24
  #       dst_port: 53
`
